(()=>{
  'use strict';
  const q=(s,r=document)=>r.querySelector(s);
  const qa=(s,r=document)=>[...r.querySelectorAll(s)];
  const PERMANENT=[
    ['plate_number','شماره پلاک'],['vehicle_type','نوع خودرو'],['body_color','رنگ بدنه'],['chassis_number','شماره شاسی'],
    ['handover_from','نام واحد/ شخص تحویل دهنده در زمان واگذاری به واحد'],['handover_to','نام شخص تحویل گیرنده در زمان واگذاری به واحد'],
    ['assignment_date','تاریخ واگذاری به واحد'],['current_location','محل استقرار فعلی'],
    ['documents_status','وضعیت مدارک(شامل بیمه بدنه، شخص ثالث، کارت خودرو و کارت سوخت)'],['remote_count','تعداد ریموت','number'],
    ['insurance_expiry_date','تاریخ انقضای بیمه'],['last_mileage','آخرین کیلومتر کارکرد','number'],['receipt_reason','علت دریافت خودرو'],
    ['return_receiver','نام واحد/ شخص تحویل گیرنده در زمان عودت از واحد'],['return_deliverer','نام شخص تحویل دهنده در زمان عودت از واحد'],
    ['return_date','تاریخ عودت از واحد'],['notes','توضیحات','textarea']
  ];
  const TEMPORARY=[
    ['plate_number','شماره پلاک'],['vehicle_type','نوع خودرو'],['body_color','رنگ بدنه'],['chassis_number','شماره شاسی'],
    ['handover_from','نام شخص تحویل دهنده در زمان واگذاری'],['handover_to','نام شخص تحویل گیرنده در زمان واگذاری'],
    ['assignment_date','تاریخ واگذاری'],['exit_time','ساعت خروج'],['entry_time','ساعت ورود'],['last_mileage','آخرین کیلومتر کارکرد','number'],
    ['fuel_status','وضعیت بنزین'],['receipt_reason','علت دریافت خودرو'],['notes','توضیحات','textarea']
  ];
  const configs={
    vehiclePermanent:{viewId:'vehiclePermanentView',table:'vehicle_permanent_records',title:'تحویل و تحول دائم',fields:PERMANENT,hasForm:true},
    vehicleTemporary:{viewId:'vehicleTemporaryView',table:'vehicle_temporary_records',title:'تحویل تحول موقت',fields:TEMPORARY,hasForm:false}
  };
  const store={vehiclePermanent:{rows:[],selected:null,query:'',filters:{}},vehicleTemporary:{rows:[],selected:null,query:'',filters:{}}};
  let ready=false,editingScope=null,editingId=null,uploadRecord=null;
  const esc=v=>typeof safe==='function'?safe(v):String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const fan=v=>typeof fa==='function'?fa(v):String(v??'');
  const isLatin=v=>/[A-Za-z0-9]/.test(String(v??''))&&!/[\u0600-\u06ff]/.test(String(v??''));
  const show=v=>v===null||v===undefined||v===''?'—':v;

  function injectStyle(){
    if(q('#bamcoVehicleManagementStyle'))return;
    const s=document.createElement('style');s.id='bamcoVehicleManagementStyle';s.textContent=`
      #appView .vehicle-view{height:calc(100dvh - 58px - var(--footer-h,34px))!important;max-height:calc(100dvh - 58px - var(--footer-h,34px))!important;overflow:hidden!important;box-sizing:border-box!important}
      #appView .vehicle-view>.vehicle-table-panel{height:calc(100% - 8px)!important;max-height:calc(100% - 8px)!important;min-height:0!important;display:flex!important;flex-direction:column!important;padding:28px 16px 16px!important;margin:4px 0!important;position:relative!important;border:1px solid #b8c8c1!important;border-radius:10px!important;background:#f8faf9!important;overflow:visible!important}
      #appView .vehicle-view .vehicle-panel-head{height:0!important;min-height:0!important;margin:0!important;padding:0!important;border:0!important}
      #appView .vehicle-view .vehicle-panel-head h3{position:absolute!important;top:-15px!important;right:18px!important;z-index:5!important;margin:0!important;padding:0 10px!important;background:#eef3f0!important;color:#145741!important;font-size:18px!important;line-height:1.7!important;font-weight:700!important;white-space:nowrap!important}
      #appView .vehicle-toolbar{display:flex!important;align-items:center!important;justify-content:flex-start!important;flex-wrap:nowrap!important;gap:10px!important;margin:0 0 12px!important;padding:0!important;overflow-x:auto!important}
      #appView .vehicle-toolbar button{flex:0 0 auto!important;border-radius:8px!important}
      #appView .vehicle-search{display:none!important;width:280px!important;min-width:280px!important;height:38px!important;border-radius:8px!important}
      #appView .vehicle-search.search-open{display:block!important}
      #appView .vehicle-table-wrap{flex:1 1 auto!important;min-height:0!important;overflow:auto!important;border:1px solid #b8c8c1!important;border-radius:10px!important;background:#fff!important;scrollbar-width:none!important}
      #appView .vehicle-table-wrap::-webkit-scrollbar{width:0!important;height:0!important;display:none!important}
      #appView table.vehicle-data-table{width:max-content!important;min-width:0!important;max-width:none!important;table-layout:fixed!important;border-collapse:collapse!important;direction:rtl!important;background:#fff!important}
      #appView table.vehicle-data-table th{position:relative!important;white-space:normal!important;vertical-align:middle!important;box-sizing:border-box!important;font-family:"B Nazanin",BNazanin,Tahoma,sans-serif!important;font-size:15px!important;line-height:1.5!important;text-align:center!important;direction:rtl!important;background:#edf3f0!important;border:1px solid #b8c8c1!important;padding:8px 7px!important}
      #appView table.vehicle-data-table td{white-space:normal!important;overflow-wrap:anywhere!important;vertical-align:top!important;box-sizing:border-box!important;font-family:"B Nazanin",BNazanin,Tahoma,sans-serif!important;font-size:15px!important;line-height:1.75!important;direction:rtl!important;text-align:right!important;border:1px solid #d1ddd8!important;padding:8px!important;background:#fff!important}
      #appView table.vehicle-data-table td.en-text{direction:ltr!important;text-align:left!important;font-family:"Times New Roman",serif!important}
      #appView table.vehicle-data-table tr.vehicle-selected td{background:#e8f3ee!important;outline:1px solid #4e917a!important;outline-offset:-1px!important}
      #appView table.vehicle-data-table tbody tr{cursor:pointer!important}
      #appView table.vehicle-data-table tbody tr:hover td{background:#f7faf8!important}
      #appView table.vehicle-data-table .vehicle-filter-row th{height:46px!important;padding:5px 6px!important;background:#eef4f1!important}
      #appView table.vehicle-data-table .vehicle-filter-row select{display:block!important;width:100%!important;height:34px!important;min-height:34px!important;margin:0!important;padding:3px 22px 3px 6px!important;box-sizing:border-box!important;border:1px solid #b8c8c1!important;border-radius:7px!important;background:#fff!important;font-family:"B Nazanin",BNazanin,Tahoma,sans-serif!important;font-size:14px!important;direction:rtl!important;text-align:right!important}
      #appView .vehicle-col-resize{position:absolute!important;top:0!important;bottom:0!important;left:-5px!important;width:10px!important;cursor:col-resize!important;z-index:20!important;touch-action:none!important}
      #appView .vehicle-col-resize::after{content:"";position:absolute;top:6px;bottom:6px;left:4px;width:1px;background:transparent}
      #appView .vehicle-col-resize:hover::after,#appView .vehicle-col-resize.dragging::after{background:#4f8d77!important}
      #appView .vehicle-form-cell{white-space:nowrap!important;text-align:center!important}
      #appView .vehicle-form-actions{display:flex!important;align-items:center!important;justify-content:center!important;gap:6px!important;flex-wrap:wrap!important}
      #appView .vehicle-form-cell button{padding:5px 10px!important;border-radius:7px!important;font-size:13.5px!important}
      #vehicleRecordDialog{width:min(940px,94vw)!important;max-width:940px!important}
      #vehicleRecordDialog .vehicle-form-grid{display:grid!important;grid-template-columns:repeat(2,minmax(0,1fr))!important;gap:12px!important}
      #vehicleRecordDialog label{display:flex!important;flex-direction:column!important;gap:5px!important;text-align:right!important}
      #vehicleRecordDialog label.span-2{grid-column:1/-1!important}
      #vehicleRecordDialog input,#vehicleRecordDialog textarea{width:100%!important;box-sizing:border-box!important;border-radius:8px!important}
      #vehicleRecordDialog textarea{min-height:90px!important;resize:vertical!important}
      @media(max-width:760px){#vehicleRecordDialog .vehicle-form-grid{grid-template-columns:1fr!important}#vehicleRecordDialog label.span-2{grid-column:auto!important}.vehicle-search{min-width:220px!important;width:220px!important}}
    `;document.head.appendChild(s);
  }

  function markup(scope){const c=configs[scope];return `<div class="panel vehicle-table-panel"><div class="panel-head vehicle-panel-head"><h3>${esc(c.title)}</h3></div><div class="vehicle-toolbar task-toolbar"><button type="button" class="primary vehicle-add">＋ افزودن</button><button type="button" class="ghost vehicle-edit" disabled>ویرایش</button><button type="button" class="danger vehicle-delete" disabled>حذف</button><button type="button" class="ghost vehicle-search-toggle" title="جست‌وجو">⌕</button><input class="vehicle-search" placeholder="جست‌وجو در جدول...">${c.hasForm?'<button type="button" class="ghost vehicle-download-blank">دانلود فرم خام</button>':''}</div><div class="vehicle-table-wrap"><table class="vehicle-data-table" data-scope="${scope}"><thead></thead><tbody></tbody></table></div></div>`}

  function ensureDialog(){
    if(q('#vehicleRecordDialog'))return;
    document.body.insertAdjacentHTML('beforeend',`<dialog id="vehicleRecordDialog" class="modal"><form id="vehicleRecordForm"><div class="modal-head"><div><h3 id="vehicleRecordTitle">ثبت اطلاعات خودرو</h3><p id="vehicleRecordHint"></p></div><button type="button" data-vehicle-close>×</button></div><div id="vehicleRecordFields" class="vehicle-form-grid"></div><div class="modal-actions"><button type="button" class="ghost" data-vehicle-close>انصراف</button><button type="submit" class="primary">ثبت</button></div></form></dialog><input id="vehicleFormUpload" type="file" accept="application/pdf,image/jpeg,image/png" hidden>`);
    qa('[data-vehicle-close]').forEach(b=>b.addEventListener('click',()=>q('#vehicleRecordDialog').close()));
    q('#vehicleRecordForm').addEventListener('submit',saveRecord);q('#vehicleFormUpload').addEventListener('change',uploadFormFile);
  }
  function inputField([key,label,type]){if(type==='textarea')return `<label class="span-2">${esc(label)}<textarea name="${key}"></textarea></label>`;if(type==='number')return `<label>${esc(label)}<input name="${key}" type="number" min="0" inputmode="numeric"></label>`;const ph=key.includes('date')?'۱۴۰۵/۰۱/۰۱':key.includes('time')?'۰۸:۳۰':'';return `<label>${esc(label)}<input name="${key}" ${ph?`placeholder="${ph}"`:''}></label>`}
  function openRecord(scope,id=null){if(typeof isManager==='function'&&!isManager())return;const c=configs[scope],row=id?store[scope].rows.find(x=>String(x.id)===String(id)):null;editingScope=scope;editingId=row?.id||null;q('#vehicleRecordTitle').textContent=row?`ویرایش ${c.title}`:`افزودن ${c.title}`;q('#vehicleRecordHint').textContent='ستون‌ها مطابق فایل اکسل مبنا هستند.';q('#vehicleRecordFields').innerHTML=c.fields.map(inputField).join('');const f=q('#vehicleRecordForm');c.fields.forEach(([key])=>{if(f.elements[key])f.elements[key].value=row?.[key]??''});q('#vehicleRecordDialog').showModal()}
  function payload(scope){const c=configs[scope],f=q('#vehicleRecordForm'),body={};c.fields.forEach(([key,,type])=>{let v=f.elements[key]?.value??'';if(type==='number')v=v===''?null:Number(String(v).replace(/[۰-۹]/g,d=>'۰۱۲۳۴۵۶۷۸۹'.indexOf(d)));else v=String(v).trim()||null;body[key]=Number.isNaN(v)?null:v});body.updated_at=new Date().toISOString();return body}
  async function saveRecord(e){e.preventDefault();if(!editingScope)return;try{const c=configs[editingScope],body=payload(editingScope);if(editingId)await update(c.table,`id=eq.${editingId}`,body);else await insert(c.table,body);q('#vehicleRecordDialog').close();toast(editingId?'اطلاعات خودرو ویرایش شد.':'اطلاعات خودرو ثبت شد.');await load(editingScope)}catch(err){toast(err.message,true)}}
  async function deleteRecord(scope){const st=store[scope],c=configs[scope],row=st.rows.find(x=>String(x.id)===String(st.selected));if(!row||!confirm('این ردیف برای همیشه حذف شود؟'))return;try{if(c.hasForm&&row.form_path)await deleteStoredFile(row.form_path).catch(()=>{});await api(`/rest/v1/${c.table}?id=eq.${encodeURIComponent(row.id)}`,{method:'DELETE',prefer:'return=minimal'});st.selected=null;toast('ردیف حذف شد.');await load(scope)}catch(err){toast(err.message,true)}}
  async function load(scope){if(typeof isManager==='function'&&!isManager())return;const c=configs[scope];try{store[scope].rows=await select(c.table,'select=*&order=id.asc');render(scope)}catch(err){const body=q(`#${c.viewId} tbody`);if(body)body.innerHTML=`<tr><td class="empty" colspan="${c.fields.length+1+(c.hasForm?1:0)}">${esc(err.message)}</td></tr>`}}
  function cellValue(row,key,index){if(key==='__row')return fan(index+1);if(key==='__form')return row.form_path?'دارای فرم':'بدون فرم';const v=row[key];return v===null||v===undefined||v===''?'':String(v)}
  function filtered(scope){const st=store[scope],c=configs[scope],keys=['__row',...c.fields.map(x=>x[0]),...(c.hasForm?['__form']:[])],query=st.query.trim().toLowerCase();return st.rows.map((r,i)=>({r,i})).filter(({r,i})=>(!query||keys.some(k=>String(cellValue(r,k,i)).toLowerCase().includes(query)))&&keys.every((k,idx)=>!st.filters[idx]||String(cellValue(r,k,i))===st.filters[idx]))}

  function render(scope){
    const c=configs[scope],st=store[scope],view=q(`#${c.viewId}`);if(!view)return;const headers=['ردیف',...c.fields.map(x=>x[1]),...(c.hasForm?['فرم تحویلی']:[])],keys=['__row',...c.fields.map(x=>x[0]),...(c.hasForm?['__form']:[])],thead=q('thead',view),tbody=q('tbody',view);
    thead.innerHTML=`<tr>${headers.map(h=>`<th>${esc(h)}<span class="vehicle-col-resize"></span></th>`).join('')}</tr><tr class="vehicle-filter-row">${keys.map((k,idx)=>{const values=[...new Set(st.rows.map((r,i)=>cellValue(r,k,i)).filter(Boolean))].sort((a,b)=>String(a).localeCompare(String(b),'fa'));return `<th><select data-filter="${idx}"><option value="">همه</option>${values.map(v=>`<option value="${esc(v)}" ${String(st.filters[idx]||'')===String(v)?'selected':''}>${esc(v)}</option>`).join('')}</select></th>`}).join('')}</tr>`;
    const rows=filtered(scope);tbody.innerHTML=rows.length?rows.map(({r,i})=>{const cells=[`<td>${fan(i+1)}</td>`,...c.fields.map(([key])=>{const v=show(r[key]);return `<td class="${isLatin(v)?'en-text':'fa-text'}">${esc(v)}</td>`})];if(c.hasForm)cells.push(`<td class="vehicle-form-cell"><div class="vehicle-form-actions">${r.form_path?`<button type="button" class="ghost vehicle-view-form" data-id="${r.id}">مشاهده</button><button type="button" class="ghost vehicle-upload-form" data-id="${r.id}">جایگزینی</button>`:`<button type="button" class="primary vehicle-upload-form" data-id="${r.id}">آپلود فرم</button>`}</div></td>`);return `<tr data-id="${r.id}" class="${String(st.selected)===String(r.id)?'vehicle-selected':''}">${cells.join('')}</tr>`}).join(''):`<tr><td class="empty" colspan="${headers.length}">موردی برای نمایش وجود ندارد.</td></tr>`;
    q('.vehicle-edit',view).disabled=!st.selected;q('.vehicle-delete',view).disabled=!st.selected;resize(scope,headers);
  }
  function defaultWidth(label){if(label==='ردیف')return 70;if(label==='فرم تحویلی')return 150;if(label.includes('توضیحات')||label.includes('مدارک'))return 300;if(label.includes('نام ')||label.includes('علت'))return 260;if(label.includes('تاریخ')||label.includes('ساعت'))return 135;if(label.includes('شماره')||label.includes('کیلومتر')||label.includes('ریموت'))return 135;return 165}
  function resize(scope,headers){const table=q(`table.vehicle-data-table[data-scope="${scope}"]`);if(!table)return;const heads=qa('thead>tr:first-child>th',table),key=`bamco-${scope}-vehicle-widths-v1`;let saved={};try{saved=JSON.parse(localStorage.getItem(key)||'{}')||{}}catch{}table.querySelector(':scope>colgroup')?.remove();const cg=document.createElement('colgroup'),cols=heads.map(()=>{const c=document.createElement('col');cg.appendChild(c);return c});table.insertBefore(cg,table.firstChild);const widths=headers.map(h=>Math.max(70,Number(saved[h])||defaultWidth(h)));const apply=()=>{let total=0;widths.forEach((w,i)=>{w=Math.max(65,Math.min(700,w));widths[i]=w;cols[i].style.width=`${w}px`;total+=w});table.style.width=`${total}px`;table.style.minWidth=`${total}px`};apply();heads.forEach((h,i)=>{const handle=q('.vehicle-col-resize',h);handle?.addEventListener('pointerdown',e=>{e.preventDefault();e.stopPropagation();const start=e.clientX,w0=widths[i];handle.classList.add('dragging');const move=ev=>{widths[i]=Math.max(65,Math.min(700,w0+start-ev.clientX));apply()},up=()=>{handle.classList.remove('dragging');const out={};headers.forEach((x,j)=>out[x]=widths[j]);try{localStorage.setItem(key,JSON.stringify(out))}catch{};window.removeEventListener('pointermove',move,true);window.removeEventListener('pointerup',up,true)};window.addEventListener('pointermove',move,true);window.addEventListener('pointerup',up,true)},{once:true})})}

  function downloadBlank(){const b64=window.BAMCO_VEHICLE_FORM_PDF_BASE64;if(!b64)return toast('فایل فرم خام در دسترس نیست.',true);const bin=atob(b64),bytes=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)bytes[i]=bin.charCodeAt(i);const url=URL.createObjectURL(new Blob([bytes],{type:'application/pdf'})),a=document.createElement('a');a.href=url;a.download='فرم تحویلی خودرو.pdf';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000)}
  const storagePath=p=>String(p).split('/').map(encodeURIComponent).join('/');
  async function storageUpload(path,file){const res=await fetch(`${SB_URL}/storage/v1/object/vehicle-forms/${storagePath(path)}`,{method:'POST',headers:{apikey:SB_KEY,Authorization:`Bearer ${state.token}`,'Content-Type':file.type||'application/octet-stream'},body:file});if(!res.ok){let msg='آپلود فرم انجام نشد.';try{const d=await res.json();msg=d.message||d.error||msg}catch{}throw new Error(msg)}}
  async function deleteStoredFile(path){const res=await fetch(`${SB_URL}/storage/v1/object/vehicle-forms/${storagePath(path)}`,{method:'DELETE',headers:{apikey:SB_KEY,Authorization:`Bearer ${state.token}`}});if(!res.ok&&res.status!==404)throw new Error('حذف فایل قبلی انجام نشد.')}
  async function openStoredFile(path){const win=window.open('about:blank','_blank');try{const res=await fetch(`${SB_URL}/storage/v1/object/authenticated/vehicle-forms/${storagePath(path)}`,{headers:{apikey:SB_KEY,Authorization:`Bearer ${state.token}`}});if(!res.ok)throw new Error('دریافت فرم انجام نشد.');const blob=await res.blob(),url=URL.createObjectURL(blob);if(win)win.location.href=url;else{const a=document.createElement('a');a.href=url;a.target='_blank';a.click()}setTimeout(()=>URL.revokeObjectURL(url),60000)}catch(err){win?.close();throw err}}
  const safeFileName=name=>String(name||'form').replace(/[^A-Za-z0-9._-]+/g,'_').slice(-100);
  function startUpload(id){const row=store.vehiclePermanent.rows.find(x=>String(x.id)===String(id));if(!row)return;uploadRecord=row;q('#vehicleFormUpload').value='';q('#vehicleFormUpload').click()}
  async function uploadFormFile(e){const file=e.target.files?.[0],row=uploadRecord;uploadRecord=null;if(!file||!row)return;if(file.size>20*1024*1024)return toast('حجم فرم نباید بیشتر از ۲۰ مگابایت باشد.',true);if(!['application/pdf','image/jpeg','image/png'].includes(file.type))return toast('فرم باید PDF، JPG یا PNG باشد.',true);const path=`permanent/${row.id}/${Date.now()}-${safeFileName(file.name)}`;try{await storageUpload(path,file);const old=row.form_path;await update('vehicle_permanent_records',`id=eq.${row.id}`,{form_path:path,updated_at:new Date().toISOString()});if(old)await deleteStoredFile(old).catch(()=>{});toast('فرم تحویلی آپلود شد.');await load('vehiclePermanent')}catch(err){toast(err.message,true)}}

  function bind(scope){const c=configs[scope],view=q(`#${c.viewId}`);if(!view||view.dataset.vehicleBound==='1')return;view.dataset.vehicleBound='1';view.innerHTML=markup(scope);q('.vehicle-add',view).addEventListener('click',()=>openRecord(scope));q('.vehicle-edit',view).addEventListener('click',()=>openRecord(scope,store[scope].selected));q('.vehicle-delete',view).addEventListener('click',()=>deleteRecord(scope));q('.vehicle-search-toggle',view).addEventListener('click',()=>{const i=q('.vehicle-search',view);i.classList.toggle('search-open');if(i.classList.contains('search-open'))i.focus()});q('.vehicle-search',view).addEventListener('input',e=>{store[scope].query=e.target.value;render(scope)});q('thead',view).addEventListener('change',e=>{if(!e.target.matches('select[data-filter]'))return;store[scope].filters[Number(e.target.dataset.filter)]=e.target.value;render(scope)});q('tbody',view).addEventListener('click',async e=>{const upload=e.target.closest('.vehicle-upload-form');if(upload){e.stopPropagation();startUpload(upload.dataset.id);return}const open=e.target.closest('.vehicle-view-form');if(open){e.stopPropagation();const row=store.vehiclePermanent.rows.find(x=>String(x.id)===String(open.dataset.id));if(row?.form_path)try{await openStoredFile(row.form_path)}catch(err){toast(err.message,true)}return}const tr=e.target.closest('tr[data-id]');if(!tr)return;store[scope].selected=Number(tr.dataset.id);render(scope)});if(c.hasForm)q('.vehicle-download-blank',view).addEventListener('click',downloadBlank);load(scope)}
  function init(){if(ready)return;const pv=q('#vehiclePermanentView'),tv=q('#vehicleTemporaryView');if(!pv||!tv)return;ready=true;injectStyle();ensureDialog();bind('vehiclePermanent');bind('vehicleTemporary');document.addEventListener('click',e=>{const b=e.target.closest('#nav button[data-view="vehiclePermanent"],#nav button[data-view="vehicleTemporary"]');if(b)setTimeout(()=>load(b.dataset.view),0)},true)}
  function boot(){init();if(ready)return;const mo=new MutationObserver(()=>{init();if(ready)mo.disconnect()});mo.observe(document.body,{childList:true,subtree:true});setTimeout(init,1500)}
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot,{once:true});else boot();
})();
